def neighbors(r,c,n):
    pts=[]
    if (c,r)!=(r,c): pts.append((c,r))
    if 2<=c<=n-1: pts.append((r,n+1-c))
    if 2<=r<=n-1: pts.append((n+1-r,c))
    if r>=2 and c>=2: pts.append((n+1-r,n+1-c))
    if r>=2 and c>=2: pts.append((n+1-c,n+1-r))
    if r>=2 and c>=2: pts.append((c,n+1-r))
    if r>=2 and c>=2: pts.append((n+1-c,r))
    return [p for p in pts if 0<=p[0]<n and 0<=p[1]<n]

def f4(g):
    n=len(g); A=[row[:] for row in g]
    unk={(r,c) for r in range(n) for c in range(n) if A[r][c]==6}
    for _ in range(50):
        progress=False
        for (r,c) in list(unk):
            vals={A[p] for p in neighbors(r,c,n) if (p not in unk) and 0<=p[0]<n and 0<=p[1]<n}
            if len(vals)==1:
                v=vals.pop(); A[r][c]=v; A[c][r]=A[c][r] if (c,r) not in unk else v
                if (c,r) in unk: unk.discard((c,r)); A[c][r]=v
                unk.discard((r,c)); progress=True
        if not progress: break
    # fallback: plain mirrors
    for (r,c) in list(unk):
        for p in [(r,n-1-c),(n-1-r,c),(n-1-r,n-1-c),(n-1-c,n-1-r),(n-1-c,r),(c,n-1-r)]:
            if 0<=p[0]<n and 0<=p[1]<n and A[p[0]][p[1]]!=6 and (p not in unk):
                A[r][c]=A[p[0]][p[1]]; A[c][r]=A[r][c]
                unk.discard((r,c)); unk.discard((c,r)); break
    return A, unk
